import assert from'node:assert/strict';import{mkdir,writeFile}from'node:fs/promises';import{fileURLToPath}from'node:url';const{chromium}=await import(process.env.MX_PLAYWRIGHT_MODULE||'playwright-core');const out=fileURLToPath(new URL('../../docs/qa/product-2026-11-18/ui-geometry',import.meta.url));await mkdir(out,{recursive:true});const b=await chromium.launch({executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',headless:true,args:['--mute-audio']});const results=[];
try{const p=await b.newPage({viewport:{width:1100,height:1400},isMobile:true,hasTouch:true,deviceScaleFactor:1});const errors=[];p.on('pageerror',e=>errors.push(e.message));
for(const layout of['original','balanced','oval','classic'])for(const[width,height]of[[320,400],[375,500],[440,782]])for(const scene of['figma','six','acting-self','acting-other','waiting-0']){
 const scale=width===440?100:110;await p.goto('http://127.0.0.1:5173/tests/fixtures/layout-audit.html?'+new URLSearchParams({layout,scene,width,height,scale,actor:scene==='waiting-0'?2:1}),{waitUntil:'domcontentloaded'});await p.locator('#audit-stage[data-ready=true]').waitFor();await p.evaluate(()=>document.fonts.ready);
 const check=await p.locator('#audit-stage').evaluate(root=>{const stage=root.getBoundingClientRect();const rect=e=>{const b=e.getBoundingClientRect();return{x:b.x-stage.x,y:b.y-stage.y,w:b.width,h:b.height};};const vis=s=>[...root.querySelectorAll(s)].filter(e=>e.checkVisibility());const boards=vis('.mx-board').map(e=>[...e.querySelectorAll('.mx-public-slot')].map(rect));const bets=vis('.mx-seat:not(.mx-seat-mine) .mx-seat-bet,.mx-seat:not(.mx-seat-mine) .mx-seat-bet-chip').map(rect);const fold=root.querySelector('.mx-operation-fold');const timer=root.querySelector('.mx-operation-fold .mx-seat-timer');const own=root.querySelector('.mx-seat-mine .mx-seat-timer');const wait=vis('.mx-seat-play-status').map(e=>({mask:getComputedStyle(e).borderRadius,avatar:getComputedStyle(e.closest('.mx-seat').querySelector('.mx-avatar-fallback')).borderRadius}));return{boards,bets,fold:fold?.checkVisibility()?rect(fold):null,timer:timer?.checkVisibility()?rect(timer):null,ownTimer:own?.checkVisibility(),otherTimers:vis('.mx-seat:not(.mx-seat-mine) .mx-seat-timer').length,wait,bubbles:vis('.mx-player-action').map(e=>({rect:rect(e),avatar:rect(e.closest('.mx-seat').querySelector('.mx-avatar-fallback')),color:getComputedStyle(e).backgroundColor}))};});
 const failures=[];const near=(a,b)=>Math.abs(a-b)<.3;for(const board of check.boards){if(!board.length)continue;if(layout!=='original'&&!near(board[0].x+board.at(-1).x+board.at(-1).w,width))failures.push('board not centered');for(let i=1;i<board.length;i++)if(layout!=='original'&&!(board[i].x-board[i-1].x-board[i-1].w>0&&board[i].x-board[i-1].x-board[i-1].w<board[i].w*.1))failures.push('card gap');}
 const hit=(a,b)=>Math.min(a.x+a.w,b.x+b.w)-Math.max(a.x,b.x)>.3&&Math.min(a.y+a.h,b.y+b.h)-Math.max(a.y,b.y)>.3;
 if(check.bets.some(a=>check.boards.flat().some(c=>hit(a,c))))failures.push('bet/card overlap');
 if(scene==='acting-self'&&(!check.timer||check.ownTimer||!check.fold||!near(check.timer.x,check.fold.x)||!near(check.timer.y,check.fold.y)||!near(check.timer.w,check.fold.w)))failures.push('own countdown location');
 if(scene==='acting-other'&&!check.otherTimers)failures.push('other countdown missing');
 if(check.wait.some(v=>v.mask!==v.avatar))failures.push('waiting silhouette');
 const id=`${layout}-${width}-${scene}`;await p.locator('#audit-stage').screenshot({path:`${out}/${id}.png`});results.push({id,layout,width,height,scale,scene,failures,check});console.log(id,failures.join(';')||'PASS');
}
assert.equal(errors.length,0,errors.join('\n'));}finally{await b.close();await writeFile(out+'/results.json',JSON.stringify(results,null,2));}assert.ok(results.every(r=>!r.failures.length),'UI failures; see results.json');
